import React from "react";
import ProfileShowcase from "./ProfileShowcase.jsx";
import {Link,useLocation} from "react-router-dom";

function EditorialLink({href,children,...props}) {
  const {pathname,search}=useLocation();
  if(href.startsWith("#"))return <Link {...props} to={pathname+search+href}>{children}</Link>;
  if(href.startsWith("/")&&!href.startsWith("//")){
    const routes={"/account/":"/signin","/quiz/":"/persona","/account/?join=1":"/join"};
    return <Link {...props} to={routes[href]??(href.startsWith("/#/")?href.slice(2):href)}>{children}</Link>;
  }
  return <a {...props} href={href}>{children}</a>;
}

